# ----------------------------------------------------------------------
# Section: AUMC and MRT in R
# ----------------------------------------------------------------------
aumc_linear <- function(time, conc) {
  ok <- !is.na(conc) & conc >= 0
  time <- time[ok]
  conc <- conc[ok]
  if (length(time) < 2) return(NA_real_)
  dt <- diff(time)
  # Linear trapezoid of t * C(t), not (t_mid)*(C_mid)
  sum((time[-1] * conc[-1] + time[-length(time)] * conc[-length(conc)]) / 2 * dt)
}

AUMC_0t <- aumc_linear(subj$TIME, subj$CONC)
MRT_0t <- AUMC_0t / AUC_lin

# Extrapolated AUMC contribution
t_last <- tail(subj$TIME, 1)
C_last <- tail(subj$CONC, 1)
AUMC_extra <- t_last * C_last / lz + C_last / lz^2
AUMC_inf <- AUMC_0t + AUMC_extra
MRT_inf <- AUMC_inf / AUC_inf
Vss <- CL * MRT_inf

data.frame(
  AUMC_0t = round(AUMC_0t, 2),
  AUMC_extra = round(AUMC_extra, 2),
  MRT_0t = round(MRT_0t, 2),
  MRT_inf = round(MRT_inf, 2),
  Vss = round(Vss, 2)
)

# ----------------------------------------------------------------------
# Section: Quality Checks
# ----------------------------------------------------------------------
pct_extra <- 100 * (AUC_inf - AUC_lin) / AUC_inf
cat("Percent extrapolated:", round(pct_extra, 1), "%\n")

